
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_pbeint_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_pbeint", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.245346953436729e+00, -4.162779136147273e+00, -4.047159441844974e+00, -3.887163460512584e+00, -3.669507704086868e+00, -3.380614605734079e+00, -3.010555781740258e+00, -2.560294772025369e+00, -2.051793874889777e+00, -1.532152077118194e+00, -1.038622992009886e+00, -6.961726443617459e-01, -5.967351883456612e-01, -4.899135801477120e-01, -3.555699394675587e-01, -2.314990252277958e-01, -1.312385457589297e-01, -4.949942748427340e-02, -1.081191576483221e-02, -1.216202148579917e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


